    }
}

contracts/EscrowDeal.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface IEscrowFactory {
    function feeRecipient() external view returns (address);
    function creationFee() external view returns (uint256);
    function cancelRefundCommission() external view returns (uint256);
    function resolver() external view returns (address);
    function sellerShareBps() external view returns (uint256);
    function buyerFavorBps() external view returns (uint256);
}

/// @title EscrowDeal V2 — per-trade buyer-funded escrow (Ethereum)
/// @notice Created and funded in one factory step. Seller fulfilment is off-chain by default; optional on-chain proof anchor.
///         Buyer release attests the fulfilment hash they reviewed. No seller payment flows on-chain.
contract EscrowDeal is ReentrancyGuard {
    using SafeERC20 for IERC20;

    enum State {
        Created,
        Funded,
        InProgress,
        Completed,
        Cancelled,
        Disputed,
        Resolved
    }

    address public factory;
    address public buyer;
    address public seller;
    address public token;
    uint256 public escrowAmount;
    address public optionalAgent;

    State public state;
    State private stateBeforeDispute;
    address public disputeOpener;
    bytes32 public deliveryProofHash;
    bytes32 public buyerAttestedProofHash;
    bool public buyerCancelRequested;
    bool public sellerCancelRequested;
    bool private initialized;

    event StateChanged(State indexed previousState, State indexed newState);
    event Funded(address indexed buyer, uint256 escrowAmount, uint256 creationFee);
    event ProofSubmitted(address indexed seller, bytes32 proofHash);
    event Released(address indexed buyer, address indexed seller, uint256 toSeller, uint256 toFee, bytes32 proofHash);
    event CancelRequested(address indexed party);
    event CancelRefused(address indexed party);
    event Cancelled(address indexed buyer, uint256 returnedAmount, uint256 cancelCommission);
    event DisputeOpened(address indexed opener);
    event DisputeWithdrawn(address indexed opener);
    event DisputeResolved(bool buyerFavor, uint256 toBuyer, uint256 toSeller, uint256 toFee);

    modifier onlyBuyer() {
        require(msg.sender == buyer, "Not buyer");
        _;
    }

    modifier onlySeller() {
        require(msg.sender == seller, "Not seller");
        _;
    }

    modifier onlyFactory() {
        require(msg.sender == factory, "Not factory");
        _;
    }

    modifier inState(State s) {
        require(state == s, "Invalid state");
        _;
    }

    constructor() {
        initialized = true;
    }

    function initialize(
        address factory_,
        address buyer_,
        address seller_,
        address token_,
        uint256 escrowAmount_,
        address optionalAgent_
    ) external {
        require(!initialized, "Already init");
        initialized = true;
        factory = factory_;
        buyer = buyer_;
        seller = seller_;
        token = token_;
        escrowAmount = escrowAmount_;
        optionalAgent = optionalAgent_;
        state = State.Created;
        emit StateChanged(State.Created, State.Created);
    }

    /// @dev Called by the factory after pulling escrow tokens and the creation fee from the buyer.
    function markFunded(uint256 creationFee) external onlyFactory inState(State.Created) {
        _transition(State.Funded);
        emit Funded(buyer, escrowAmount, creationFee);
    }

    function _transition(State next) internal {
        State prev = state;
        state = next;
        emit StateChanged(prev, next);
    }

    /// @notice Optional seller anchor of fulfilment hash (chat/API is the default). Does not require seller to pay trade tokens.
    function submitProof(bytes32 proofHash) external nonReentrant onlySeller {
        require(state == State.Funded || state == State.InProgress, "Invalid state");
        require(proofHash != bytes32(0), "Empty proof");
        deliveryProofHash = proofHash;
        if (state == State.Funded) {
            _transition(State.InProgress);
        }
        emit ProofSubmitted(seller, proofHash);
    }

    /// @notice Buyer releases escrow after reviewing fulfilment. `proofHash` is the hash the buyer attests they reviewed.
    function approveRelease(bytes32 proofHash) external nonReentrant onlyBuyer {
        require(state == State.Funded || state == State.InProgress, "Invalid state");
        require(proofHash != bytes32(0), "Empty proof");
        if (deliveryProofHash != bytes32(0)) {
            require(proofHash == deliveryProofHash, "Proof mismatch");
        }
        buyerAttestedProofHash = proofHash;

        IEscrowFactory f = IEscrowFactory(factory);
        uint256 toSeller = (escrowAmount * f.sellerShareBps()) / 10_000;
        uint256 toFee = escrowAmount - toSeller;
        IERC20(token).safeTransfer(seller, toSeller);
        _distributeFee(f.feeRecipient(), toFee);
        _transition(State.Completed);
        emit Released(buyer, seller, toSeller, toFee, proofHash);
    }

    function requestCancel() external nonReentrant {
        require(state == State.Funded || state == State.InProgress, "Cannot cancel");
        if (msg.sender == seller) {
            sellerCancelRequested = true;
            emit CancelRequested(seller);
            _refundTradeAmountAndCancel();
            return;
        }
        require(msg.sender == buyer, "Not party");
        require(!buyerCancelRequested, "Already requested");
        buyerCancelRequested = true;
        emit CancelRequested(buyer);
    }

    function refuseCancel() external nonReentrant {
        require(state == State.Funded || state == State.InProgress, "Cannot cancel");
        require(msg.sender == seller, "Only seller can refuse");
        require(buyerCancelRequested, "Nothing to refuse");
        buyerCancelRequested = false;
        emit CancelRefused(seller);
    }

    /// @dev Seller-initiated close: refund escrow trade amount to buyer (funder) minus cancel commission; creation fee stays with protocol.
    function _refundTradeAmountAndCancel() internal {
        IEscrowFactory f = IEscrowFactory(factory);
        uint256 commission = f.cancelRefundCommission();
        require(escrowAmount >= commission, "Trade too small");
        uint256 refund = escrowAmount - commission;
        IERC20(token).safeTransfer(buyer, refund);
        if (commission > 0) {
            IERC20(token).safeTransfer(f.feeRecipient(), commission);
        }
        _transition(State.Cancelled);
        emit Cancelled(buyer, refund, commission);
    }

    function openDispute() external nonReentrant {
        require(msg.sender == buyer || msg.sender == seller, "Not party");
        require(state == State.Funded || state == State.InProgress, "Invalid state");
        stateBeforeDispute = state;
        disputeOpener = msg.sender;
        _transition(State.Disputed);
        emit DisputeOpened(msg.sender);
    }

    /// @notice Lets the dispute opener or configured resolver withdraw and resume the prior trade state.
    function withdrawDispute() external nonReentrant inState(State.Disputed) {
        IEscrowFactory f = IEscrowFactory(factory);
        require(msg.sender == disputeOpener || msg.sender == f.resolver(), "Not authorized");
        State resumeState = stateBeforeDispute;
        require(resumeState == State.Funded || resumeState == State.InProgress, "Invalid resume state");
        _transition(resumeState);
        address opener = disputeOpener;
        disputeOpener = address(0);
        emit DisputeWithdrawn(opener);
    }

    /// @notice Factory `resolver` wallet rules the outcome and moves escrow tokens (buyer refund vs seller release split).
    function resolveDispute(bool buyerFavor) external nonReentrant inState(State.Disputed) {
        IEscrowFactory f = IEscrowFactory(factory);
        require(msg.sender == f.resolver(), "Not resolver");
        uint256 toBuyer;
        uint256 toSeller;
        uint256 toFee;
        if (buyerFavor) {
            toBuyer = escrowAmount;
            IERC20(token).safeTransfer(buyer, toBuyer);
        } else {
            toSeller = (escrowAmount * f.sellerShareBps()) / 10_000;
            toFee = escrowAmount - toSeller;
            IERC20(token).safeTransfer(seller, toSeller);
            _distributeFee(f.feeRecipient(), toFee);
        }
        _transition(State.Resolved);
        emit DisputeResolved(buyerFavor, toBuyer, toSeller, toFee);
    }

    /// @dev Routes 100% of protocol fee to feeRecipient on standard trades; splits 50/50 with optionalAgent when assigned.
    function _distributeFee(address feeRecipient, uint256 totalFee) internal {
        if (totalFee == 0) return;
        if (optionalAgent != address(0)) {
            uint256 toPartner = totalFee / 2;
            uint256 toProtocol = totalFee - toPartner;
            if (toPartner > 0) IERC20(token).safeTransfer(optionalAgent, toPartner);
            if (toProtocol > 0) IERC20(token).safeTransfer(feeRecipient, toProtocol);
        } else {
            IERC20(token).safeTransfer(feeRecipient, totalFee);
        }
    }
}

contracts/EscrowFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "@openzeppelin/contracts/proxy/Clones.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "./EscrowDeal.sol";

/// @notice V2 factory — clones an escrow and funds it in one transaction from the buyer (msg.sender).
contract EscrowFactory is Ownable {
    using SafeERC20 for IERC20;

    address public immutable implementation;
    address public feeRecipient;
    address public resolver;
    uint256 public creationFee = 1e6;
    /// @notice Deducted from escrow to fee recipient when the seller closes a funded trade (cancel-refund).
    uint256 public cancelRefundCommission = 1e6;

    uint256 public sellerShareBps = 9000;
    uint256 public feeShareBps = 1000;
    uint256 public buyerFavorBps = 9000;

    bool public agentModeEnabled;

    mapping(address => bool) public whitelistedTokens;
    mapping(address => bool) public isEscrow;

    event EscrowCreated(
        address indexed escrow,
        address indexed buyer,
        address indexed seller,
        address token,
        uint256 amount,
        address optionalAgent
    );
    event FeeRecipientUpdated(address indexed feeRecipient);
    event ResolverUpdated(address indexed resolver);
    event TokenWhitelistUpdated(address indexed token, bool allowed);
    event AgentModeUpdated(bool enabled);
    event CreationFeeUpdated(uint256 fee);
    event CancelRefundCommissionUpdated(uint256 fee);

    constructor(
        address implementation_,
        address feeRecipient_,
        address resolver_,
        address usdc,
        address usdt,
        address thirdStable
    ) Ownable(msg.sender) {
        implementation = implementation_;
        feeRecipient = feeRecipient_;
        resolver = resolver_;
        _setToken(usdc, true);
        _setToken(usdt, true);
        if (thirdStable != address(0)) _setToken(thirdStable, true);
    }

    /// @notice Clone a deal, pull trade amount + creation fee from the buyer, and mark the deal Funded.
    function createAndFund(
        address seller,
        address token,
        uint256 amount,
        address optionalAgent
    ) external returns (address escrow) {
        address buyer = msg.sender;
        require(buyer != address(0) && seller != address(0), "Zero address");
        require(buyer != seller, "Same party");
        require(amount > 0, "Zero amount");
        require(whitelistedTokens[token], "Token not allowed");

        uint256 fee = creationFee;
        escrow = Clones.clone(implementation);
        EscrowDeal deal = EscrowDeal(escrow);
        deal.initialize(address(this), buyer, seller, token, amount, optionalAgent);

        IERC20(token).safeTransferFrom(buyer, escrow, amount);
        IERC20(token).safeTransferFrom(buyer, feeRecipient, fee);
        deal.markFunded(fee);

        isEscrow[escrow] = true;
        emit EscrowCreated(escrow, buyer, seller, token, amount, optionalAgent);
    }

    function setFeeRecipient(address feeRecipient_) external onlyOwner {
        feeRecipient = feeRecipient_;
        emit FeeRecipientUpdated(feeRecipient_);
    }

    function setResolver(address resolver_) external onlyOwner {
        resolver = resolver_;
        emit ResolverUpdated(resolver_);
    }

    function setAgentMode(bool enabled) external onlyOwner {
        agentModeEnabled = enabled;
        emit AgentModeUpdated(enabled);
    }

    function setCreationFee(uint256 fee) external onlyOwner {
        creationFee = fee;
        emit CreationFeeUpdated(fee);
    }

    function setCancelRefundCommission(uint256 fee) external onlyOwner {
        cancelRefundCommission = fee;
        emit CancelRefundCommissionUpdated(fee);
    }

    function setToken(address token, bool allowed) external onlyOwner {
        _setToken(token, allowed);
    }

    function _setToken(address token, bool allowed) internal {
        whitelistedTokens[token] = allowed;
        emit TokenWhitelistUpdated(token, allowed);
    }
}

contracts/ResolverRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "@openzeppelin/contracts/access/Ownable.sol";

interface IResolvableEscrow {
    function resolveDispute(bool buyerFavor) external;
    function withdrawDispute() external;
    function optionalAgent() external view returns (address);
}

/// @notice Two-tier dispute resolver registry & router for 2Pescrow factories.
/// - Platform resolvers (`isResolver`) can resolve or withdraw any disputed escrow.
/// - Special resolvers (`isSpecialResolver`) can ONLY resolve or withdraw escrows
///   where `escrow.optionalAgent() == msg.sender`, isolating external partners
///   (lawyers / Telegram escrow hosts) strictly to their own referred clients' trades.
contract ResolverRouter is Ownable {
    mapping(address => bool) public isResolver;
    mapping(address => bool) public isSpecialResolver;
    address[] private _resolvers;
    address[] private _specialResolvers;

    event ResolverAdded(address indexed resolver);
    event ResolverRemoved(address indexed resolver);
    event SpecialResolverAdded(address indexed resolver);
    event SpecialResolverRemoved(address indexed resolver);
    event DisputeResolved(address indexed escrow, address indexed resolver, bool buyerFavor, bool specialTier);
    event DisputeWithdrawn(address indexed escrow, address indexed resolver, bool specialTier);

    constructor(address[] memory initialResolvers) Ownable(msg.sender) {
        for (uint256 i = 0; i < initialResolvers.length; i++) {
            _addResolver(initialResolvers[i]);
        }
    }

    function _addResolver(address account) internal {
        require(account != address(0), "Zero address");
        if (isResolver[account]) return;
        isResolver[account] = true;
        _resolvers.push(account);
        emit ResolverAdded(account);
    }

    function _addSpecialResolver(address account) internal {
        require(account != address(0), "Zero address");
        if (isSpecialResolver[account]) return;
        isSpecialResolver[account] = true;
        _specialResolvers.push(account);
        emit SpecialResolverAdded(account);
    }

    function addResolver(address account) external onlyOwner {
        _addResolver(account);
    }

    function addResolvers(address[] calldata accounts) external onlyOwner {
        for (uint256 i = 0; i < accounts.length; i++) {
            _addResolver(accounts[i]);
        }
    }

    function removeResolver(address account) external onlyOwner {
        require(isResolver[account], "Not a resolver");
        isResolver[account] = false;
        _removeFromArray(_resolvers, account);
        emit ResolverRemoved(account);
    }

    function addSpecialResolver(address account) external onlyOwner {
        _addSpecialResolver(account);
    }

    function removeSpecialResolver(address account) external onlyOwner {
        require(isSpecialResolver[account], "Not a special resolver");
        isSpecialResolver[account] = false;
        _removeFromArray(_specialResolvers, account);
        emit SpecialResolverRemoved(account);
    }

    function _removeFromArray(address[] storage list, address account) internal {
        uint256 len = list.length;
        for (uint256 i = 0; i < len; i++) {
            if (list[i] == account) {
                list[i] = list[len - 1];
                list.pop();
                break;
            }
        }
    }

    function getResolvers() external view returns (address[] memory) {
        return _resolvers;
    }

    function getSpecialResolvers() external view returns (address[] memory) {
        return _specialResolvers;
    }

    function canResolveEscrow(address account, address escrow) public view returns (bool) {
        if (isResolver[account]) return true;
        if (isSpecialResolver[account] && escrow != address(0)) {
            return IResolvableEscrow(escrow).optionalAgent() == account;
        }
        return false;
    }

    function resolveDispute(address escrow, bool buyerFavor) external {
        require(escrow != address(0), "Zero escrow");
        bool isPlatform = isResolver[msg.sender];
        bool isScopedPartner = !isPlatform && isSpecialResolver[msg.sender] && IResolvableEscrow(escrow).optionalAgent() == msg.sender;
        require(isPlatform || isScopedPartner, "Not authorized resolver");
        IResolvableEscrow(escrow).resolveDispute(buyerFavor);
        emit DisputeResolved(escrow, msg.sender, buyerFavor, isScopedPartner);
    }

    function withdrawDispute(address escrow) external {
        require(escrow != address(0), "Zero escrow");
        bool isPlatform = isResolver[msg.sender];
        bool isScopedPartner = !isPlatform && isSpecialResolver[msg.sender] && IResolvableEscrow(escrow).optionalAgent() == msg.sender;
        require(isPlatform || isScopedPartner, "Not authorized resolver");
        IResolvableEscrow(escrow).withdrawDispute();
        emit DisputeWithdrawn(escrow, msg.sender, isScopedPartner);
    }
}
